window.products.push({"id":353010,"name":"Pewter Celtic Cross with Irish Triquetra Knots Christmas Ornament and Holiday Decoration","category":"homeandappliances","retail price":9.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/519-OtrmiEL._AC_.jpg","description":"This classic Celtic Cross Ornament is hand cast and hand finished in solid Pewter with a shiny finish resembling silver. This unique Holiday Ornament comes with a Red Satin Ribbon ready to hang from your Christmas Tree or as a Holiday Decoration for your home. We use Fine American pewter that is lead free and Made in the USA. Our Pewter Ornaments make terrific gifts for family, friends, business associates and of course, your home. We hope you and your loved ones enjoy this keepsake for years to come!","images":["https://m.media-amazon.com/images/I/519-OtrmiEL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Trilogy Jewelry","source_asin":"B00GKURRMS","category_path":"Home & Kitchen"},"sku":"BM-353010","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00GKURRMS","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00GKURRMS","price_pending":true,"merchant_ready":false});
